9	declare_lint_rule! {
10	    /// Disallow the use of global `eval()`.
11	    ///
12	    /// The `eval()` function evaluates the passed string as a _JavaScript_ code.
13	    /// The executed code can access and mutate variables in the scope where the function is called.
14	    ///
15	    /// The use of `eval()` exposes to [security risks and performance issues](https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/eval#never_use_eval!).
16	    /// If the executed code is somehow affected by a malicious party,
17	    /// then you may end up executing malicious code with the privileges of the caller.
18	    /// Moreover, changing variables in the caller's scope is expensive in modern _JavaScript_ interpreters.
19	    ///
20	    /// ## Examples
21	    ///
22	    /// ### Invalid
23	    ///
24	    /// ```js,expect_diagnostic
25	    /// eval("var a = 0");
26	    /// ```
27	    ///
28	    /// ```js,expect_diagnostic
29	    /// (0, globalThis.eval)("var a = 0")
30	    /// ```
31	    ///
32	    /// ```js,expect_diagnostic
33	    /// f(eval);
34	    /// ```
35	    ///
36	    /// ```js,expect_diagnostic
37	    /// const aliasedEval = eval;
38	    /// ```
39	    ///
40	    /// ### Valid
41	    ///
42	    /// ```cjs
43	    /// function f(eval) {
44	    ///     eval("let a = 0;");
45	    /// }
46	    /// ```
47	    ///
48	    /// The rule is not able to detect cases where the global object is aliased:
49	    ///
50	    /// ```js
51	    /// let foo = globalThis;
52	    /// foo.eval("let a = 0;");
53	    /// ```
54	    pub NoGlobalEval {
55	        version: "1.5.0",
56	        name: "noGlobalEval",
57	        language: "js",
58	        sources: &[RuleSource::Eslint("no-eval").same()],
59	        recommended: true,
60	        severity: Severity::Error,
61	    }
62	}
