87	            },
88	        ).note(markup! {
89	            "See the "<Hyperlink href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/eval#never_use_eval!">"MDN web docs"</Hyperlink>" for more details."
90	        })
91	        .note(
92	            markup! {
93	            "Refactor the code so that it doesn't need to call "<Emphasis>"eval()"</Emphasis>"."
94	        }))
