    /// Disallow the use of implied `eval()`.
    ///
    /// Passing a string as the first argument to `setTimeout`, `setInterval`, or
    /// `setImmediate` causes the string to be evaluated as _JavaScript_ code, just
    /// like `eval()`. This is known as _implied eval_.
    ///
    /// Implied `eval()` exposes the same security risks and performance issues as a
    /// direct call to `eval()`: if the executed code is affected by a malicious party,
    /// then you may end up executing malicious code, and the interpreter cannot optimize
    /// the evaluated code.
    ///
    /// ## Examples
    ///
    /// ### Invalid
    ///
    /// ```js,expect_diagnostic
    /// setTimeout("alert('Hi!');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// setInterval("alert('Hi!');", 100);
    /// ```
    ///
    /// ```js,expect_diagnostic
    /// window.setTimeout("alert('Hi!');", 100);
    /// ```
    ///
    /// ### Valid
    ///
    /// ```js
    /// setTimeout(function () {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    ///
    /// ```js
    /// setInterval(() => {
    ///     alert("Hi!");
    /// }, 100);
    /// ```
    pub NoImpliedEval {
        version: "next",
        name: "noImpliedEval",
        language: "js",
        sources: &[],
        recommended: false,
        severity: Severity::Error,
    }
}

impl Rule for NoImpliedEval {
    type Query = Semantic<JsCallExpression>;
    type State = ();
    type Signals = Option<Self::State>;
    type Options = NoImpliedEvalOptions;

    fn run(ctx: &RuleContext<Self>) -> Self::Signals {
        let call = ctx.query();
        let model = ctx.model();

        // Resolve the callee, taking into account access through `window` or
        // `globalThis` (e.g. `window.setTimeout`, `globalThis['setInterval']`).
        let callee = call.callee().ok()?.omit_parentheses();
        let (reference, name) = global_identifier(&callee)?;

        if !matches!(
            name.text(),
            "setTimeout" | "setInterval" | "setImmediate"
        ) {
            return None;
        }

        // Skip when the function name is shadowed by a local binding.
        if model.binding(&reference).is_some() {
            return None;
        }

        let args = call.arguments().ok()?;
        let first_arg = args.args().into_iter().next()?.ok()?;
        let expr = first_arg.as_any_js_expression()?;

        is_string_expression(expr).then_some(())
    }

    fn diagnostic(ctx: &RuleContext<Self>, _: &Self::State) -> Option<RuleDiagnostic> {
        let node = ctx.query();
        Some(
            RuleDiagnostic::new(
                rule_category!(),
                node.range(),
                markup! {
                    "Implied "<Emphasis>"eval()"</Emphasis>" is not allowed."
                },
            )
            .note(markup! {
                "Passing strings to functions like "<Emphasis>"setTimeout"</Emphasis>", "<Emphasis>"setInterval"</Emphasis>", or "<Emphasis>"setImmediate"</Emphasis>" is a form of implied "<Emphasis>"eval()"</Emphasis>" and can lead to security and performance issues."
            })
            .note(markup! {
                "Use a function instead of a string."
            }),
        )
    }
}

/// Returns `true` if the expression is, or evaluates to, a string that would be
/// interpreted as code when passed to a timer scheduling function.
///
/// This covers string literals, template literals without substitutions, and
/// `+` concatenation expressions where at least one operand is a string. Any
/// surrounding parentheses are ignored.
fn is_string_expression(expr: &AnyJsExpression) -> bool {
    match expr.clone().omit_parentheses() {
        AnyJsExpression::AnyJsLiteralExpression(
            AnyJsLiteralExpression::JsStringLiteralExpression(_),
        ) => true,
        AnyJsExpression::JsTemplateExpression(template) => {
            // A tagged template does not produce a plain string, and a template
            // with substitutions may resolve to a non-code value at runtime.
            template.tag().is_none()
                && template
                    .elements()
                    .into_iter()
                    .all(|element| matches!(element, AnyJsTemplateElement::JsTemplateChunkElement(_)))
        }
        AnyJsExpression::JsBinaryExpression(binary) => {
            binary.operator() == Ok(JsBinaryOperator::Plus)
                && (binary.left().is_ok_and(|left| is_string_expression(&left))
                    || binary.right().is_ok_and(|right| is_string_expression(&right)))
        }
        _ => false,
    }
}
